import React, { useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import ChatButton from '../chat/ChatButton';
import ChatSidebar from '../chat/ChatSidebar';
import ThemeToggle from './ThemeToggle'; // we will create this as part of ThemeContext or component

const Header = () => {
  const { user } = useAuth();
  const [chatOpen, setChatOpen] = useState(false);

  return (
    <>
      <header className="flex items-center justify-between bg-white dark:bg-gray-900 p-4 shadow">
        <div className="text-xl font-bold">NewsSite</div>
        <nav className="space-x-4">
          {/* category links could go here */}
        </nav>
        <div className="flex items-center space-x-2">
          {user && <ChatButton onClick={() => setChatOpen(true)} />}
          <ThemeToggle />
        </div>
      </header>
      <ChatSidebar isOpen={chatOpen} onClose={() => setChatOpen(false)} />
    </>
  );
};

export default Header;
